 CASE WHEN NOT (NEW.incognito=0 AND ((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only')))) THEN 'withdraw' WHEN NEW.purged_at IS NOT NULL THEN 'delete' ELSE 'put' END,CASE WHEN (CASE WHEN NOT (NEW.incognito=0 AND ((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only')))) THEN 'withdraw' WHEN NEW.purged_at IS NOT NULL THEN 'delete' ELSE 'put' END)='put' THEN json_object('id',NEW.id,'workspace_id',NEW.workspace_id,'user_id',NEW.user_id,'title',NEW.title,'title_source',NEW.title_source,'last_message_at',NEW.last_message_at,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'deleted_at',NEW.deleted_at,'web_search',NEW.web_search,'instructions',NEW.instructions,'project_id',NEW.project_id,'memory_injection',NEW.memory_injection,'memory_checked_at',NEW.memory_checked_at,'pinned_tier',NEW.pinned_tier,'pinned_provider',NEW.pinned_provider,'pinned_model',NEW.pinned_model,'active_leaf_id',NEW.active_leaf_id,'incognito',NEW.incognito,'pinned_at',NEW.pinned_at,'archived_at',NEW.archived_at,'stay_provider',NEW.stay_provider,'kind',NEW.kind,'handoff_from_id',NEW.handoff_from_id,'run_cap_micro_usd',NEW.run_cap_micro_usd,'purged_at',NEW.purged_at) ELSE NULL END,unixepoch()*1000,unixepoch()*1000 FROM sync_state WHERE workspace_id=NEW.workspace_id;
 INSERT INTO sync_records (workspace_id,user_id,table_name,record_key,event_id,device_id,clock,version,revision,operation,created_at,updated_at)
 SELECT workspace_id,user_id,table_name,record_key,id,device_id,clock,version,
 COALESCE((SELECT revision FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='threads' AND record_key=NEW.id),0)+1,operation,created_at,updated_at
 FROM sync_outbox WHERE id=(SELECT device_id||':'||seq FROM sync_state WHERE workspace_id=NEW.workspace_id)
 ON CONFLICT(workspace_id,table_name,record_key) DO UPDATE SET
