oute_intent OR NEW.route_complexity IS NOT OLD.route_complexity OR NEW.best_cost_micro_usd IS NOT OLD.best_cost_micro_usd OR NEW.escalated_from_id IS NOT OLD.escalated_from_id OR NEW.feedback IS NOT OLD.feedback OR NEW.reasoning_summary IS NOT OLD.reasoning_summary))
