DROP TRIGGER sync_files_update;
CREATE TRIGGER sync_files_update AFTER UPDATE ON files
 WHEN EXISTS (SELECT 1 FROM sync_state WHERE workspace_id=NEW.workspace_id AND enabled=1 AND applying=0) AND ((1) AND ((((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only'))) AND (NEW.thread_id IS NULL OR (EXISTS (SELECT 1 FROM threads t WHERE t.id=NEW.thread_id AND t.workspace_id=NEW.workspace_id AND t.incognito=0 AND (t.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=t.project_id AND p.privacy_mode!='local_only'))))) AND NEW.may_send=1 AND NOT EXISTS (SELECT 1 FROM folder_files ff WHERE ff.file_id=NEW.id) AND (NEW.thread_id IS NOT NULL OR EXISTS (SELECT 1 FROM message_files mf JOIN messages m ON m.id=mf.message_id JOIN threads t ON t.id=m.thread_id WHERE mf.file_id=NEW.id AND t.incognito=0 AND (t.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=t.project_id AND p.privacy_mode!='local_only'))) OR EXISTS (SELECT 1 FROM project_files pf JOIN projects p ON p.id=pf.project_id WHERE pf.file_id=NEW.id AND pf.deleted_at IS NULL AND p.privacy_mode!='local_only'))) OR EXISTS (SELECT 1 FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='files' AND record_key=NEW.id))) AND ((SELECT force_capture FROM sync_state WHERE workspace_id=NEW.workspace_id)=1 OR NOT EXISTS (SELECT 1 FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='files' AND record_key=NEW.id) OR (NEW.id IS NOT OLD.id OR NEW.workspace_id IS NOT OLD.workspace_id OR NEW.user_id IS NOT OLD.user_id OR NEW.name IS NOT OLD.name OR NEW.mime IS NOT OLD.mime OR NEW.size_bytes IS NOT OLD.size_bytes OR NEW.sha256 IS NOT OLD.sha256 OR NEW.width IS NOT OLD.width OR NEW.height IS NOT OLD.height OR NEW.token_estimate IS NOT OLD.token_estimate OR NEW.parse_status IS NOT OLD.parse_status OR NEW.parse_error IS NOT OLD.parse_error OR NEW.project_id IS NOT OLD.project_id OR NEW.thread_id IS NOT OLD.thread_id OR NEW.created_at IS NOT OLD.created_at OR NEW.updated_at IS NOT OLD.updated_at OR NEW.deleted_at IS NOT OLD.deleted_at OR NEW.may_send IS NOT OLD.may_send))
 BEGIN
 UPDATE sync_state SET seq=seq+1,clock=clock+1 WHERE workspace_id=NEW.workspace_id;
 INSERT INTO sync_outbox (id,workspace_id,user_id,table_name,record_key,device_id,seq,clock,version,operation,payload,created_at,updated_at)
 SELECT device_id||':'||seq,NEW.workspace_id,NEW.user_id,'files',NEW.id,device_id,seq,clock,
 json_set(COALESCE((SELECT version FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='files' AND record_key=NEW.id),'{}'),'$."'||device_id||'"',seq),
 CASE WHEN NOT (((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only'))) AND (NEW.thread_id IS NULL OR (EXISTS (SELECT 1 FROM threads t WHERE t.id=NEW.thread_id AND t.workspace_id=NEW.workspace_id AND t.incognito=0 AND (t.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=t.project_id AND p.privacy_mode!='local_only'))))) AND NEW.may_send=1 AND NOT EXISTS (SELECT 1 FROM folder_files ff WHERE ff.file_id=NEW.id) AND (NEW.thread_id IS NOT NULL OR EXISTS (SELECT 1 FROM message_files mf JOIN messages m ON m.id=mf.message_id JOIN threads t ON t.id=m.thread_id WHERE mf.file_id=NEW.id AND t.incognito=0 AND (t.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=t.project_id AND p.privacy_mode!='local_only'))) OR EXISTS (SELECT 1 FROM project_files pf JOIN projects p ON p.id=pf.project_id WHERE pf.file_id=NEW.id AND pf.deleted_at IS NULL AND p.privacy_mode!='local_only'))) THEN 'withdraw' WHEN NEW.deleted_at IS NOT NULL THEN 'delete' ELSE 'put' END,CASE WHEN (CASE WHEN NOT (((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only'))) AND (NEW.thread_id IS NULL OR (EXISTS (SELECT 1 FROM threads t WHERE t.id=NEW.thread_id AND t.workspace_id=NEW.workspace_id AND t.incognito=0 AND (t.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=t.project_id AND p.privacy_mode!='local_only'))))) AND NEW.may_send=1 AND NOT EXISTS (SELECT 1 FROM folder_files ff WHERE ff.file_id=NEW.id) AND (NEW.thread_id IS NOT NULL OR EXISTS (SELECT 1 FROM message_files mf JOIN messages m ON m.id=mf.message_id JOIN threads t ON t.id=m.thread_id WHERE mf.file_id=NEW.id AND t.incognito=0 AND (t.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=t.project_id AND p.privacy_mode!='local_only'))) OR EXISTS (SELECT 1 FROM project_files pf JOIN projects p ON p.id=pf.project_id WHERE pf.file_id=NEW.id AND pf.deleted_at IS NULL AND p.privacy_mode!='local_only'))) THEN 'withdraw' WHEN NEW.deleted_at IS NOT NULL THEN 'delete' ELSE 'put' END)='put' THEN json_object('id',NEW.id,'workspace_id',NEW.workspace_id,'user_id',NEW.user_id,'name',NEW.name,'mime',NEW.mime,'size_bytes',NEW.size_bytes,'sha256',NEW.sha256,'width',NEW.width,'height',NEW.height,'token_estimate',NEW.token_estimate,'parse_status',NEW.parse_status,'parse_error',NEW.parse_error,'project_id',NEW.project_id,'thread_id',NEW.thread_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'deleted_at',NEW.deleted_at,'may_send',NEW.may_send) ELSE NULL END,unixepoch()*1000,unixepoch()*1000 FROM sync_state WHERE workspace_id=NEW.workspace_id;
 INSERT INTO sync_records (workspace_id,user_id,table_name,record_key,event_id,device_id,clock,version,revision,operation,created_at,updated_at)
 SELECT workspace_id,user_id,table_name,record_key,id,device_id,clock,version,
 COALESCE((SELECT revision FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='files' AND record_key=NEW.id),0)+1,operation,created_at,updated_at
 FROM sync_outbox WHERE id=(SELECT device_id||':'||seq FROM sync_state WHERE workspace_id=NEW.workspace_id)
 ON CONFLICT(workspace_id,table_name,record_key) DO UPDATE SET
 event_id=excluded.event_id,device_id=excluded.device_id,clock=excluded.clock,version=excluded.version,
 revision=excluded.revision,operation=excluded.operation,updated_at=excluded.updated_at;
 DELETE FROM sync_outbox WHERE workspace_id=NEW.workspace_id AND table_name='files' AND operation='put' AND record_key IN (SELECT record_key FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='files' AND operation!='put');
 END;

