 INSERT INTO sync_outbox (id,workspace_id,user_id,table_name,record_key,device_id,seq,clock,version,operation,payload,created_at,updated_at)
 SELECT device_id||':'||seq,NEW.workspace_id,NEW.user_id,'run_steps',NEW.id,device_id,seq,clock,
 json_set(COALESCE((SELECT version FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='run_steps' AND record_key=NEW.id),'{}'),'$."'||device_id||'"',seq),
 CASE WHEN NOT (EXISTS (SELECT 1 FROM runs r JOIN threads t ON t.id=r.thread_id WHERE r.id=NEW.run_id AND r.workspace_id=NEW.workspace_id AND r.status IN ('done','stopped','error') AND t.incognito=0 AND (t.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=t.project_id AND p.privacy_mode!='local_only')))) THEN 'withdraw' ELSE 'put' END,CASE WHEN (CASE WHEN NOT (EXISTS (SELECT 1 FROM runs r JOIN threads t ON t.id=r.thread_id WHERE r.id=NEW.run_id AND r.workspace_id=NEW.workspace_id AND r.status IN ('done','stopped','error') AND t.incognito=0 AND (t.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=t.project_id AND p.privacy_mode!='local_only')))) THEN 'withdraw' ELSE 'put' END)='put' THEN json_object('id',NEW.id,'workspace_id',NEW.workspace_id,'user_id',NEW.user_id,'run_id',NEW.run_id,'seq',NEW.seq,'kind',NEW.kind,'text',NEW.text,'native',NEW.native,'request_id',NEW.request_id,'tool_name',NEW.tool_name,'tool_call_id',NEW.tool_call_id,'input',NEW.input,'output',NEW.output,'is_error',NEW.is_error,'cost_micro_usd',NEW.cost_micro_usd,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'approval',NEW.approval,'images',NEW.images,'flags',NEW.flags) ELSE NULL END,unixepoch()*1000,unixepoch()*1000 FROM sync_state WHERE workspace_id=NEW.workspace_id;
 INSERT INTO sync_records (workspace_id,user_id,table_name,record_key,event_id,device_id,clock,version,revision,operation,created_at,updated_at)
 SELECT workspace_id,user_id,table_name,record_key,id,device_id,clock,version,
 COALESCE((SELECT revision FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='run_steps' AND record_key=NEW.id),0)+1,operation,created_at,updated_at
 FROM sync_outbox WHERE id=(SELECT device_id||':'||seq FROM sync_state WHERE workspace_id=NEW.workspace_id)
 ON CONFLICT(workspace_id,table_name,record_key) DO UPDATE SET
 event_id=excluded.event_id,device_id=excluded.device_id,clock=excluded.clock,version=excluded.version,
 revision=excluded.revision,operation=excluded.operation,updated_at=excluded.updated_at;
 DELETE FROM sync_outbox WHERE workspace_id=NEW.workspace_id AND table_name='run_steps' AND operation='put' AND record_key IN (SELECT record_key FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='run_steps' AND operation!='put');
 END;

DROP TRIGGER sync_run_changes_update;
CREATE TRIGGER sync_run_changes_update AFTER UPDATE ON run_changes
 WHEN EXISTS (SELECT 1 FROM sync_state WHERE workspace_id=NEW.workspace_id AND enabled=1 AND applying=0) AND ((1) AND ((EXISTS (SELECT 1 FROM runs r JOIN threads t ON t.id=r.thread_id WHERE r.id=NEW.run_id AND r.workspace_id=NEW.workspace_id AND r.status IN ('done','stopped','error') AND t.incognito=0 AND (t.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=t.project_id AND p.privacy_mode!='local_only')))) OR EXISTS (SELECT 1 FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='run_changes' AND record_key=NEW.id))) AND ((SELECT force_capture FROM sync_state WHERE workspace_id=NEW.workspace_id)=1 OR NOT EXISTS (SELECT 1 FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='run_changes' AND record_key=NEW.id) OR (NEW.id IS NOT OLD.id OR NEW.workspace_id IS NOT OLD.workspace_id OR NEW.user_id IS NOT OLD.user_id OR NEW.run_id IS NOT OLD.run_id OR NEW.step_id IS NOT OLD.step_id OR NEW.path IS NOT OLD.path OR NEW.from_path IS NOT OLD.from_path OR NEW.before IS NOT OLD.before OR NEW.after IS NOT OLD.after OR NEW.status IS NOT OLD.status OR NEW.created_at IS NOT OLD.created_at OR NEW.updated_at IS NOT OLD.updated_at OR NEW.before_sha IS NOT OLD.before_sha OR NEW.after_sha IS NOT OLD.after_sha OR NEW.batch_id IS NOT OLD.batch_id))
 BEGIN
 UPDATE sync_state SET seq=seq+1,clock=clock+1 WHERE workspace_id=NEW.workspace_id;
 INSERT INTO sync_outbox (id,workspace_id,user_id,table_name,record_key,device_id,seq,clock,version,operation,payload,created_at,updated_at)
 SELECT device_id||':'||seq,NEW.workspace_id,NEW.user_id,'run_changes',NEW.id,device_id,seq,clock,
 json_set(COALESCE((SELECT version FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='run_changes' AND record_key=NEW.id),'{}'),'$."'||device_id||'"',seq),
 CASE WHEN NOT (EXISTS (SELECT 1 FROM runs r JOIN threads t ON t.id=r.thread_id WHERE r.id=NEW.run_id AND r.workspace_id=NEW.workspace_id AND r.status IN ('done','stopped','error') AND t.incognito=0 AND (t.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=t.project_id AND p.privacy_mode!='local_only')))) THEN 'withdraw' ELSE 'put' END,CASE WHEN (CASE WHEN NOT (EXISTS (SELECT 1 FROM runs r JOIN threads t ON t.id=r.thread_id WHERE r.id=NEW.run_id AND r.workspace_id=NEW.workspace_id AND r.status IN ('done','stopped','error') AND t.incognito=0 AND (t.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=t.project_id AND p.privacy_mode!='local_only')))) THEN 'withdraw' ELSE 'put' END)='put' THEN json_object('id',NEW.id,'workspace_id',NEW.workspace_id,'user_id',NEW.user_id,'run_id',NEW.run_id,'step_id',NEW.step_id,'path',NEW.path,'from_path',NEW.from_path,'before',NEW.before,'after',NEW.after,'status',NEW.status,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'before_sha',NEW.before_sha,'after_sha',NEW.after_sha,'batch_id',NEW.batch_id) ELSE NULL END,unixepoch()*1000,unixepoch()*1000 FROM sync_state WHERE workspace_id=NEW.workspace_id;
 INSERT INTO sync_records (workspace_id,user_id,table_name,record_key,event_id,device_id,clock,version,revision,operation,created_at,updated_at)
 SELECT workspace_id,user_id,table_name,record_key,id,device_id,clock,version,
 COALESCE((SELECT revision FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='run_changes' AND record_key=NEW.id),0)+1,operation,created_at,updated_at
 FROM sync_outbox WHERE id=(SELECT device_id||':'||seq FROM sync_state WHERE workspace_id=NEW.workspace_id)
 ON CONFLICT(workspace_id,table_name,record_key) DO UPDATE SET
 event_id=excluded.event_id,device_id=excluded.device_id,clock=excluded.clock,version=excluded.version,
 revision=excluded.revision,operation=excluded.operation,updated_at=excluded.updated_at;
 DELETE FROM sync_outbox WHERE workspace_id=NEW.workspace_id AND table_name='run_changes' AND operation='put' AND record_key IN (SELECT record_key FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='run_changes' AND operation!='put');
 END;

DROP TRIGGER sync_project_files_update;
CREATE TRIGGER sync_project_files_update AFTER UPDATE ON project_files
 WHEN EXISTS (SELECT 1 FROM sync_state WHERE workspace_id=NEW.workspace_id AND enabled=1 AND applying=0) AND ((1) AND (((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only')) AND EXISTS (SELECT 1 FROM files f WHERE f.id=NEW.file_id AND f.may_send=1) AND NOT EXISTS (SELECT 1 FROM folder_files ff WHERE ff.file_id=NEW.file_id)) OR EXISTS (SELECT 1 FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='project_files' AND record_key=json_array(NEW.project_id,NEW.file_id)))) AND ((SELECT force_capture FROM sync_state WHERE workspace_id=NEW.workspace_id)=1 OR NOT EXISTS (SELECT 1 FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='project_files' AND record_key=json_array(NEW.project_id,NEW.file_id)) OR (NEW.id IS NOT OLD.id OR NEW.workspace_id IS NOT OLD.workspace_id OR NEW.user_id IS NOT OLD.user_id OR NEW.project_id IS NOT OLD.project_id OR NEW.file_id IS NOT OLD.file_id OR NEW.created_at IS NOT OLD.created_at OR NEW.updated_at IS NOT OLD.updated_at OR NEW.deleted_at IS NOT OLD.deleted_at))
 BEGIN
 UPDATE sync_state SET seq=seq+1,clock=clock+1 WHERE workspace_id=NEW.workspace_id;
 INSERT INTO sync_outbox (id,workspace_id,user_id,table_name,record_key,device_id,seq,clock,version,operation,payload,created_at,updated_at)
 SELECT device_id||':'||seq,NEW.workspace_id,NEW.user_id,'project_files',json_array(NEW.project_id,NEW.file_id),device_id,seq,clock,
 json_set(COALESCE((SELECT version FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='project_files' AND record_key=json_array(NEW.project_id,NEW.file_id)),'{}'),'$."'||device_id||'"',seq),
 CASE WHEN NOT ((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only')) AND EXISTS (SELECT 1 FROM files f WHERE f.id=NEW.file_id AND f.may_send=1) AND NOT EXISTS (SELECT 1 FROM folder_files ff WHERE ff.file_id=NEW.file_id)) THEN 'withdraw' WHEN NEW.deleted_at IS NOT NULL THEN 'delete' ELSE 'put' END,CASE WHEN (CASE WHEN NOT ((NEW.project_id IS NULL OR EXISTS (SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.workspace_id=NEW.workspace_id AND p.privacy_mode!='local_only')) AND EXISTS (SELECT 1 FROM files f WHERE f.id=NEW.file_id AND f.may_send=1) AND NOT EXISTS (SELECT 1 FROM folder_files ff WHERE ff.file_id=NEW.file_id)) THEN 'withdraw' WHEN NEW.deleted_at IS NOT NULL THEN 'delete' ELSE 'put' END)='put' THEN json_object('id',NEW.id,'workspace_id',NEW.workspace_id,'user_id',NEW.user_id,'project_id',NEW.project_id,'file_id',NEW.file_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'deleted_at',NEW.deleted_at) ELSE NULL END,unixepoch()*1000,unixepoch()*1000 FROM sync_state WHERE workspace_id=NEW.workspace_id;
 INSERT INTO sync_records (workspace_id,user_id,table_name,record_key,event_id,device_id,clock,version,revision,operation,created_at,updated_at)
 SELECT workspace_id,user_id,table_name,record_key,id,device_id,clock,version,
 COALESCE((SELECT revision FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='project_files' AND record_key=json_array(NEW.project_id,NEW.file_id)),0)+1,operation,created_at,updated_at
 FROM sync_outbox WHERE id=(SELECT device_id||':'||seq FROM sync_state WHERE workspace_id=NEW.workspace_id)
 ON CONFLICT(workspace_id,table_name,record_key) DO UPDATE SET
 event_id=excluded.event_id,device_id=excluded.device_id,clock=excluded.clock,version=excluded.version,
 revision=excluded.revision,operation=excluded.operation,updated_at=excluded.updated_at;
 DELETE FROM sync_outbox WHERE workspace_id=NEW.workspace_id AND table_name='project_files' AND operation='put' AND record_key IN (SELECT record_key FROM sync_records WHERE workspace_id=NEW.workspace_id AND table_name='project_files' AND operation!='put');
 END;

CREATE TRIGGER sync_thread_retained AFTER INSERT ON sync_outbox
 WHEN NEW.table_name='threads' AND NEW.operation='delete'
 BEGIN
 UPDATE sync_outbox SET retained=(SELECT json_object('project_id',project_id,'kind',kind) FROM threads WHERE workspace_id=NEW.workspace_id AND id=NEW.record_key) WHERE id=NEW.id;
 END;
